{
  "title": "The Mirror Siege",
  "gate_token": "7JRlyELEKmakcAA6NhWMkA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The Glass Diver enters the ruined square through a shattered window.",
      "visual_description": "A vast, rubble-strewn square before a collapsed royal gate, moonlight leaking through broken windows. The Glass Diver steps out of a mirror shard, coat reflecting the fractured city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer consults her map beneath a torn banner.",
      "visual_description": "Mara kneels among fallen cobblestones, unrolling a stained parchment map. A tattered royal banner flutters above her on a bent pole.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning from a windowsill.",
      "visual_description": "An old stone window frame holds the Oracle Lamp, its single flame-eye glowing. Its light casts nervous shadows on the wall.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Sleeping Tax Collector dozes behind a ledger desk in an alcove.",
      "visual_description": "A half-collapsed alcove with a wooden desk. The Sleeping Tax Collector snores softly, head on a ledger book, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scurries under an abandoned cart to scout ahead.",
      "visual_description": "A rusty iron cart overturned in the street. The Tin Fox peeks from beneath it, key-wind tail still, blue glass eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The group gathers at the castle gate's broken portcullis.",
      "visual_description": "A massive portcullis half-crumbled, its iron teeth bent. Glass Diver, Mara, Oracle Lamp (held by Mara), and Tin Fox stand before it.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Mara points to a cursed tower looming behind the gate.",
      "visual_description": "Beyond the gate, a twisted spire with black vines climbing its walls, a faint purple glow pulsing from its top window.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The Tin Fox triggers a hidden trap and dodges a falling stone.",
      "visual_description": "A section of wall collapses as a stone block swings down. The Tin Fox leaps sideways, metal joints glinting.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The Oracle Lamp illuminates a magic door covered in runes.",
      "visual_description": "A tall stone door carved with glowing runes, set in a shadowy arch. The Oracle Lamp's light makes the runes pulse rhythmically.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara deciphers the runes while the Sleeping Tax Collector snores nearby.",
      "visual_description": "Mara traces a rune with her finger, ink-stained coat sleeves brushing the door. The Sleeping Tax Collector lies slumped on a bench a few paces away.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver swims through the magic door's mirror surface.",
      "visual_description": "The rune door becomes a vertical mirror. The Glass Diver steps into it, his form rippling as he passes through.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, the Glass Diver finds a room filled with old royal banners.",
      "visual_description": "A circular chamber hung with moth-eaten banners bearing faded crests. Dust motes float in a single beam of light from a high window.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The Oracle Lamp warns of armored footsteps approaching outside.",
      "visual_description": "The Oracle Lamp's flame-eye widens, casting a quick red tint. From beyond the door comes the sound of heavy, rhythmic steps.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The group hides behind a collapsed pillar as patrols pass.",
      "visual_description": "A broken marble pillar lies across the floor. Mara, Tin Fox, and the Lamp press against it, as a line of armored figures marches past in the hallway.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver returns through a mirror, carrying a rescued captive.",
      "visual_description": "The Glass Diver emerges from a tall standing mirror, a hooded figure leaning on his shoulder. The room is lit by the Lamp's steady glow.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They race across a crumbling bridge as the city shakes.",
      "visual_description": "A narrow stone bridge spanning a dark chasm, its sides broken. The entire group runs, the bridge cracking behind them. The Sleeping Tax Collector is dragged along by Mara.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge collapses behind them as they reach safety.",
      "visual_description": "The last section of bridge falls into the mist below. The group stands on solid ground, panting. The Oracle Lamp's flame steadies.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Mara marks the ruined city on her map as dawn breaks.",
      "visual_description": "Pale sunrise over the distant ruins. Mara makes a cross on her map with a quill. The others rest beside her. The Glass Diver's helmet catches the first light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

